mapper.select:
SELECT v.id, v.section, v.reason, v.summary, v.data, v.created_by, u.name AS created_by_name, v.created_at
  FROM life_versions v LEFT JOIN admin_users u ON u.id = v.created_by
 WHERE v.id = #{id}

mapper.delete:
DELETE FROM life_versions
 WHERE section = #{section}
   AND id NOT IN (SELECT id FROM (SELECT id FROM life_versions WHERE section = #{section} ORDER BY id DESC LIMIT #{keep}) recent)
